// Builds the JavaScript for each n8n Code node from src/lib/*.js.
// It keeps only the top-level functions/constants an adapter actually uses (transitively), so every
// Code node stays readable and self-contained (n8n Code nodes cannot require() local files).

const fs = require('fs');
const path = require('path');
const acorn = require('acorn');
const walk = require('acorn-walk');

const LIB_DIR = path.join(__dirname, '..', '..', 'src', 'lib');
const LIB_ORDER = ['util', 'places', 'website', 'pagespeed', 'problems', 'ai', 'sheet', 'followup', 'steps'];

function stripForEmbedding(src) {
  return src.replace(/\/\/ @node-only-start[\s\S]*?\/\/ @node-only-end\n?/g, '').replace(/\/\/ @export[\s\S]*$/, '');
}

function referencedIdentifiers(node) {
  const names = new Set();
  walk.full(node, (n) => {
    if (n.type === 'Identifier') names.add(n.name);
  });
  return names;
}

function declNames(stmt) {
  if (stmt.type === 'FunctionDeclaration') return [stmt.id.name];
  if (stmt.type === 'VariableDeclaration') return stmt.declarations.map((d) => d.id.name);
  return [];
}

let cache = null;

function loadLibrary() {
  if (cache) return cache;
  const decls = new Map(); // name -> { name, lib, order, code, deps }
  let order = 0;
  for (const lib of LIB_ORDER) {
    const file = path.join(LIB_DIR, `${lib}.js`);
    const src = stripForEmbedding(fs.readFileSync(file, 'utf8'));
    const comments = [];
    const ast = acorn.parse(src, { ecmaVersion: 2022, sourceType: 'script', onComment: comments });
    for (const stmt of ast.body) {
      const names = declNames(stmt);
      if (!names.length) {
        if (stmt.type === 'ExpressionStatement' && stmt.expression.type === 'Literal') continue; // 'use strict'
        throw new Error(`${lib}.js: unsupported top-level statement at offset ${stmt.start}; only functions and constants may be embedded`);
      }
      // Attach the comment block that sits directly above the declaration.
      let start = stmt.start;
      for (let i = comments.length - 1; i >= 0; i--) {
        const c = comments[i];
        const gap = src.slice(c.end, start);
        if (c.end <= start && /^\s*$/.test(gap) && !/\n\s*\n/.test(gap)) start = c.start;
        else if (c.end <= start) break;
      }
      const code = src.slice(start, stmt.end);
      const deps = referencedIdentifiers(stmt);
      for (const name of names) {
        if (decls.has(name)) throw new Error(`Duplicate top-level name "${name}" in ${lib}.js and ${decls.get(name).lib}.js`);
        decls.set(name, { name, lib, order: order++, code, deps, group: names.join(',') });
      }
    }
  }
  cache = decls;
  return decls;
}

// Returns the library code needed by `adapterCode`, in dependency-safe source order.
function bundleFor(adapterCode, extraEntries) {
  const decls = loadLibrary();
  const wrapped = `(async function adapter() {\n${adapterCode}\n})`;
  const ast = acorn.parse(wrapped, { ecmaVersion: 2022, sourceType: 'script', allowReturnOutsideFunction: true });
  const needed = new Set();
  const queue = [...referencedIdentifiers(ast), ...(extraEntries || [])].filter((n) => decls.has(n));
  while (queue.length) {
    const name = queue.pop();
    if (needed.has(name)) continue;
    needed.add(name);
    for (const dep of decls.get(name).deps) if (decls.has(dep) && !needed.has(dep)) queue.push(dep);
  }
  const chosen = [...needed].map((n) => decls.get(n)).sort((a, b) => a.order - b.order);
  const seenGroups = new Set();
  const parts = [];
  let currentLib = '';
  for (const d of chosen) {
    if (seenGroups.has(d.group)) continue;
    seenGroups.add(d.group);
    if (d.lib !== currentLib) {
      parts.push(`// ---- ${d.lib}.js ----`);
      currentLib = d.lib;
    }
    parts.push(d.code);
  }
  return parts.join('\n\n');
}

function codeNodeSource({ title, purpose, adapter }) {
  const lib = bundleFor(adapter);
  const header = [
    `// ${title}`,
    ...(purpose ? purpose.split('\n').map((l) => `// ${l}`) : []),
    '// Generated by Client Finder Agent. You normally never need to edit this node: change the',
    '// values in the "⚙️ Settings" node instead.',
  ].join('\n');
  const body = lib ? `${lib}\n\n// ---- this step ----\n${adapter.trim()}\n` : `${adapter.trim()}\n`;
  const source = `${header}\n\n${body}`;
  // Fail the build if the generated code is not valid JavaScript.
  acorn.parse(`(async function n8nCode() {\n${source}\n})`, { ecmaVersion: 2022, sourceType: 'script' });
  return source;
}

module.exports = { LIB_ORDER, stripForEmbedding, loadLibrary, bundleFor, codeNodeSource };
